import assert from 'assert';
import {createPauseComparison,newerSnapshot,outcomeSummary,phaseDescription} from './debug-presentation.js';
const value=(name,value,truncated=false)=>({name,value,truncated,declaration_line:3});
const snap=(pause_id,variables,extra={})=>({session_id:1,revision:pause_id,phase:'paused',pause_id,variables,stack:[{oid:10,name:'f'}],...extra});
const comparison=createPauseComparison();
assert.equal(comparison.update(snap(1,[value('x',null)]))[0].state,'same');
let rows=comparison.update(snap(2,[value('x','NULL'),value('y','new')]));
assert.equal(rows[0].state,'changed');assert.equal(rows[0].previous.value,null);assert.equal(rows[1].state,'added');
assert.equal(comparison.update(snap(2,[value('x','NULL')],{revision:99}))[0].state,'changed');
assert.equal(comparison.update(snap(3,[value('x','NULL')]))[0].state,'same');
assert.equal(comparison.update(snap(4,[value('x','prefix',true)]))[0].state,'changed');
assert.equal(comparison.update(snap(5,[value('x','prefix',true)]))[0].state,'partial');
assert.equal(comparison.update(snap(6,[value('x','other')],{stack:[{oid:20,name:'g'}]}))[0].state,'same');
assert.equal(comparison.update(snap(1,[value('x','again')],{session_id:2}))[0].state,'same');
console.log('PASS pause comparison: NULL/text, new variables, stable poll, repeated line, truncated values, frame/session reset');
assert(!newerSnapshot(snap(2,[]),snap(1,[])));assert(!newerSnapshot(snap(2,[]),snap(2,[])));
assert(newerSnapshot(snap(2,[]),snap(3,[])));assert(!newerSnapshot(snap(2,[]),snap(3,[],{unchanged:true})));
assert(!newerSnapshot(snap(2,[],{session_id:3}),snap(3,[],{session_id:2})));
assert(newerSnapshot(snap(2,[]),snap(1,[],{session_id:2})));
assert.equal(outcomeSummary({call:'failed',rollback:'confirmed',cancellation_requested:true}).call,'Ошибка SQL');
assert.equal(outcomeSummary({call:'unknown',rollback:'unconfirmed',text:'Вызов выполнен'}).callTone,'warning');
assert.equal(outcomeSummary({call:'succeeded',rollback:'unconfirmed'}).rollbackTone,'warning');
assert(phaseDescription({phase:'stopping'}).includes('подтверждения отката'));
console.log('PASS debug presentation: stale responses, separate SQL/rollback/cancellation and stopping explanation');
